/**
 * @summary Get dashboard summary (current weather + active alerts + risk overview)
 */
export const GetDashboardSummaryQueryParams = zod.object({
  locationId: zod.coerce.number().nullish(),
});

export const GetDashboardSummaryResponse = zod.object({
  location: zod
    .object({
      id: zod.number(),
      userId: zod.number(),
      name: zod.string(),
      lat: zod.number(),
      lng: zod.number(),
      city: zod.string().nullish(),
      state: zod.string().nullish(),
      isDefault: zod.boolean(),
      createdAt: zod.coerce.date(),
    })
    .optional(),
  currentWeather: zod.object({
    temperature: zod.number().describe("Temperature in Fahrenheit"),
    feelsLike: zod.number(),
    humidity: zod.number(),
    windSpeed: zod.number().describe("Wind speed in mph"),
    windGust: zod.number().optional(),
    cloudCover: zod.number().describe("Cloud cover percentage 0-100"),
    precipitation: zod.number().describe("Current precipitation in inches"),
    uvIndex: zod.number(),
    visibility: zod.number().optional(),
    weatherCode: zod.number().describe("WMO weather condition code"),
    weatherDescription: zod.string(),
    isDay: zod.boolean(),
    updatedAt: zod.coerce.date(),
  }),
  todayForecast: zod.object({
    date: zod.coerce.date(),
    tempMax: zod.number(),
    tempMin: zod.number(),
    feelsLikeMax: zod.number(),
    feelsLikeMin: zod.number(),
    precipitation: zod.number().describe("Total precipitation in inches"),
    precipitationProbability: zod
      .number()
      .describe("Precipitation probability 0-100"),
    windSpeedMax: zod.number(),
    windGustMax: zod.number(),
    cloudCover: zod.number(),
    uvIndexMax: zod.number(),
    sunrise: zod.string(),
    sunset: zod.string(),
    weatherCode: zod.number(),
    weatherDescription: zod.string(),
    soilMoisture: zod.number().nullish(),
    soilTemperature: zod.number().nullish(),
    evapotranspiration: zod.number().nullish(),
  }),
  activeAlertCount: zod.number(),
  activeAlerts: zod.array(
    zod.object({
      id: zod.number(),
      userId: zod.number(),
      locationId: zod.number().nullish(),
      farmProfileId: zod.number().nullish(),
      type: zod.enum([
        "frost",
        "hard_freeze",
        "extreme_heat",
        "heat_stress",
        "heavy_precipitation",
        "flash_flood",
        "drought",
        "high_wind",
        "hail",
        "harvest_disruption",
        "late_season_frost",
        "winter_storm",
      ]),
      severity: zod.enum(["watch", "warning", "critical"]),
      title: zod.string(),
      message: zod.string(),
      triggerValue: zod.number().nullish(),
      isRead: zod.boolean(),
      triggeredAt: zod.coerce.date(),
      expiresAt: zod.coerce.date().nullish(),
    }),
  ),
  upcomingExtremes: zod.array(
    zod.object({
      type: zod.enum([
        "frost",
        "hard_freeze",
        "extreme_heat",
        "heat_stress",
        "heavy_precipitation",
        "flash_flood",
        "drought",
        "high_wind",
        "hail",
        "harvest_disruption",
        "late_season_frost",
        "winter_storm",
      ]),
      date: zod.coerce.date(),
      severity: zod.enum(["watch", "warning", "critical"]),
      description: zod.string(),
    }),
  ),
  weeklyPrecipitation: zod
    .number()
    .describe("Total precipitation expected in next 7 days (inches)"),
  weeklyTempRange: zod.object({
    min: zod.number(),
    max: zod.number(),
  }),
});

